// Banner photo per country guide, keyed by the guide's URL slug. Generated by
// `scripts/apply_new_images.py` from the files in public/countries/ — do not edit by hand.
// A country with no entry simply shows no banner.
export const COUNTRY_HERO: Record<string, string> = {};

export function countryHeroFor(slug: string): string | null {
  return COUNTRY_HERO[slug] ?? null;
}
